/**
 * content.js — 3D Brain + Animated Vertical Hovering Lightning Bolts Chrome Extension
 *
 * Workflow:
 * 1. User highlights text -> 3D pink brain icon appears above and to the right of the selection.
 * 2. User clicks the 3D brain icon -> the 3 yellow lightning bolts appear above the brain and
 *    hover vertically (up and down) while the prompt is analyzed and executed by the LLM/API.
 * 3. Once the model finishes thinking and has the generated response ready -> automatically
 *    performs the icon-to-chat-box transition and displays the layman's explanation!
 */

(() => {
  const IS_TOP_FRAME = (window === window.top);
  const BRAIN_URI = "data:image/png;base64,";
  const BRAIN_EYES_URI = "data:image/png;base64,";
  const SLEEP_MASK_URI = "data:image/png;base64,";
  const SLEEP_Z1_URI = "data:image/png;base64,";
  const SLEEP_Z2_URI = "data:image/png;base64,";
  const GLASSES_URI = "data:image/png;base64,";
  const NOTEPAD_BASE_URI = "data:image/png;base64,";
  const NOTEPAD_LINES_URI = "data:image/png;base64,";
  const NOTEPAD_FLIP_URI = "data:image/png;base64,";
  const PENCIL_URI = "data:image/png;base64,";
  const BOLT_LEFT_URI = "data:image/png;base64,";
  const BOLT_CENTER_URI = "data:image/png;base64,";
  const BOLT_RIGHT_URI = "data:image/png;base64,";
  const FULL_ICON_URI = "data:image/png;base64,";

  const ICON_SIZE = 64;
  const ICON_RADIUS = ICON_SIZE / 2;

  let floatingIcon = null;
  let curveOverlay = null;
  let chatSidebar = null;
  let currentHighlight = '';
  let sessionHighlight = ''; // Locked for the entire open-to-close chat session
  let sessionMessages = [];  // Continuous session history; system prompt is only set once per session open
  let iconOrigin = { x: 0, y: 0, baselineY: 0 };
  let isAnimating = false;
  let isThinking = false;
  let isChatOpen = false;
  let isMinimized = false;
  let minimizedCornerSide = 'right';
  let minimizedCustomPos = null; // Set when the user moves the brain via triple-click while minimized
  let currentDockSide = 'right';

  function buildSessionSystemPrompt() {
    return [
      `You are a helpful, unrestricted AI assistant built into a Chrome Extension. Your communication style uses clear, digestible everyday language, simple vernacular, and intuitive explanations (layman's terms) so complex ideas are effortless for any human to understand.`,
      ``,
      `How each chat session works:`,
      `1. Initial Prompt (Highlighted Text): The user opens the chat box by highlighting text on a webpage. For that initial message ONLY, explain what the highlighted text means in layman's terms, provide an intuitive analogy and helpful background context, and ask if they have any follow-up questions or want to dive deeper.`,
      `2. All Subsequent Prompts in the Session: Function as a normal, full-featured AI assistant while maintaining full memory of the conversation history. Answer ANY question or perform ANY task the user asks—whether it builds on the highlighted text (such as providing links to academic papers, equations, code, or deeper details) or is completely unrelated to the highlighted text—using clear, approachable, easy-to-digest language. Never limit what you can do or answer based on the initial highlighted text, and never repeat the initial 4-part template on follow-up messages.`
    ].join('\n');
  }

  const DOMAIN_KNOWLEDGE = [
    {
      match: /angular power spectrum|power spectrum|multipole|cmb|cosmic microwave|anisotrop/i,
      title: "Angular Power Spectrum (Cosmology & Astrophysics)",
      plain: "An **angular power spectrum** is a chart that measures how strongly features on the sky (such as temperature ripples in the Cosmic Microwave Background or the clustering of galaxies) vary at different angular sizes—from huge patterns stretching across the whole sky down to tiny pinpoint fluctuations.",
      analogy: "Think of a musical chord played by an orchestra. A sound equalizer breaks that complex sound wave down into bass, midrange, and treble frequencies so you can see how loud each pitch is. An **angular power spectrum** does the exact same thing for a map of the sky: instead of sound frequencies, it breaks the sky map down by **spot size on the sky** (from giant wide blobs to tiny speckles) so cosmologists can read the 'cosmic fingerprint' of the universe!",
      background: "By measuring the peaks and valleys of the angular power spectrum (using telescopes like Planck, WMAP, ACT, DES, and DESI), physicists determined the exact recipe of our universe—proving it is ~68% dark energy, ~27% dark matter, and ~5% ordinary atoms—and how fast structures grew over 13.8 billion years.",
      mechanisms: "Mathematically, a sky map is expanded into spherical harmonics (multipoles l). Small multipoles (low l) represent giant angles across the sky, while large multipoles (high l) represent tiny angular scales. Plotting the variance C_l at each multipole l gives the angular power spectrum.",
      papers: [
        "• **[Cosmic Microwave Background Anisotropies (Hu & Dodelson, 2002)](https://arxiv.org/abs/astro-ph/0110414)** — The classic, accessible review paper explaining how the angular power spectrum encodes the physics of the early universe.",
        "• **[Planck 2018 Results. VI. Cosmological Parameters](https://arxiv.org/abs/1807.06209)** — The landmark Planck Collaboration paper showing the full CMB temperature and polarization angular power spectra.",
        "• **[DES Year 3 Results: Cosmological Constraints from Galaxy Clustering and Weak Lensing](https://arxiv.org/abs/2105.13549)** — Shows how modern galaxy surveys use angular power spectra to map dark matter across cosmic time."
      ]
    },
    {
      match: /primordial black hole|pbh|black hole|accreti|dark matter|gravitational seed/i,
      title: "Primordial Black Holes (PBHs) & Dark Matter Accretion",
      plain: "Unlike ordinary black holes that form when giant stars run out of fuel and collapse, **primordial black holes (PBHs)** are hypothetical black holes that formed in the very first fraction of a second after the Big Bang from ultra-dense pockets of energy. **Supermassive primordial black holes** could act as early 'gravitational seeds' that pull in surrounding dark matter and gas to grow the giant galaxies we see today.",
      analogy: "Think of forming snowballs on a winter field. Normal stellar black holes are like snowballs rolled together much later after snow has settled. **Primordial black holes** are like dense ice cores formed right during the initial blizzard—because they were there from the very start, they had a huge head start to roll up surrounding snow (dark matter and gas) into giant snow boulders (supermassive black holes at the centers of galaxies).",
      background: "Astronomers have recently spotted surprisingly massive black holes in the very early universe (using telescopes like JWST and surveys like DES and DESI) that seem too big to have grown from ordinary stars alone. Physicists study whether primordial black holes could explain both these early monster black holes and part of the universe's mysterious dark matter.",
      mechanisms: "If PBHs make up even a tiny fraction of dark matter (measured as f_PBH), their intense gravity pulls in surrounding dark matter halos and gas in the early universe, accelerating galaxy formation and leaving measurable signatures in gravitational lensing surveys like DES Y3.",
      papers: [
        "• **[Primordial Black Holes as Dark Matter: Recent Developments (Carr & Kuhnel, 2020)](https://arxiv.org/abs/2006.02838)** — Comprehensive overview of how primordial black holes form and how astronomers test for them.",
        "• **[Primordial Black Holes (Sasaki et al., 2018)](https://arxiv.org/abs/1801.05235)** — Detailed review of PBH gravitational wave and lensing signatures.",
        "• **[Search More PBH Papers on arXiv](https://arxiv.org/search/?query=primordial+black+holes+dark+matter&searchtype=all)** — Live arXiv preprint feed on primordial black holes."
      ]
    },
    {
      match: /redshift|strong-lens|gravitational lens|desi|spectroscopy|galaxy|galaxies|cosmol/i,
      title: "High-Redshift Galaxies & Gravitational Lensing",
      plain: "Because the universe is expanding, light traveling to us from very distant, ancient galaxies gets stretched out into longer, redder wavelengths—a phenomenon called **redshift**. **High-redshift galaxies** are galaxies so far away that we are seeing them as they looked billions of years ago in the young universe. **Gravitational lensing** happens when a massive galaxy in the foreground bends and magnifies the light from an even more distant galaxy behind it, acting like a natural cosmic magnifying glass.",
      analogy: "Imagine hearing an ambulance siren drop in pitch as it drives away from you—that's the sound version of **redshift**! And **gravitational lensing** is just like looking at a distant candle through the curved base of a wine glass: the heavy foreground galaxy bends space like glass bends light, magnifying faint background galaxies so telescopes like DESI can study them.",
      background: "By measuring how much a foreground galaxy bends light (strong and weak lensing) alongside its redshift distance (via spectroscopy), astrophysicists can weigh the total mass of galaxies—including invisible dark matter—and map how cosmic structure evolved over billions of years.",
      mechanisms: "Spectrographs like DESI split a galaxy's light into a rainbow spectrum to find exact chemical lines and see how far they shifted toward the red end, giving a 3D map of where both the lens galaxy and the background source galaxy sit in cosmic time.",
      papers: [
        "• **[Strong Gravitational Lensing (Treu, 2010)](https://arxiv.org/abs/1003.5567)** — Foundational review of how strong gravitational lenses measure galaxy mass and cosmology.",
        "• **[DESI 2024 VI: Cosmological Constraints from Baryon Acoustic Oscillations](https://arxiv.org/abs/2404.03002)** — Key DESI collaboration paper mapping high-redshift galaxies."
      ]
    },
    {
      match: /supernova|type ia|sh0es|ztf|hubble|h0|calibrat|phantom crossing/i,
      title: "Type Ia Supernovae & Cosmic Distance Calibration (H0)",
      plain: "To measure how fast the universe is expanding today (the **Hubble constant, H0**), astronomers use **Type Ia supernovae**—exploding white dwarf stars that always reach nearly the same peak brightness. Because we know their true brightness, we can tell how far away they are by how dim they look from Earth, provided our telescope measurements are carefully calibrated without systematic offsets.",
      analogy: "Think of Type Ia supernovae as **100-watt lightbulbs** scattered across a dark highway. Because every bulb is 100 watts, if one looks four times dimmer than another, you know it is twice as far away! Calibrating telescopes like ZTF and SH0ES is like making sure your camera lens doesn't have a smudge on it before estimating distances.",
      background: "One of the biggest mysteries in modern physics is the 'Hubble Tension'—measurements of the universe's expansion rate using nearby supernovae (like SH0ES and ZTF) disagree slightly with measurements from the early universe's cosmic microwave background.",
      mechanisms: "A white dwarf star pulls gas from a companion star until it hits a strict mass limit (1.44 solar masses) and explodes with uniform brightness. Combining nearby ZTF supernovae with Cepheid-calibrated SH0ES supernovae requires matching their brightness scales to within a few hundredths of a magnitude.",
      papers: [
        "• **[A Comprehensive Measurement of the Local Value of the Hubble Constant with 1 km/s/Mpc Uncertainty from the Hubble Space Telescope and the SH0ES Team (Riess et al., 2022)](https://arxiv.org/abs/2112.04510)** — The primary SH0ES distance-ladder paper."
      ]
    },
    {
      match: /entangle|bell inequalit|non-local|spacelike|eigenstate|spin-1\/2|wave function|superluminal|shannon/i,
      title: "Quantum Entanglement & Bell Non-Locality",
      plain: "When two quantum particles become entangled, their states are linked together no matter how far apart they are in the universe. Measuring one particle immediately tells you the state of its partner—even light-years away—yet you still cannot use this effect to send faster-than-light messages.",
      analogy: "Imagine two magic coins spun inside sealed boxes—one in New York and one in Tokyo. While spinning, neither coin has landed on heads or tails yet. The instant you open the New York box and see **Heads**, the Tokyo coin immediately settles on **Tails**.",
      background: "Einstein called this *'spooky action at a distance'*, but experiments testing **Bell inequalities** proved quantum particles truly share non-local correlations, forming the basis of quantum computing and quantum cryptography.",
      mechanisms: "Before measurement, the two particles share a single joint wave function. Measuring one collapses that shared state instantaneously across any distance, but because each individual measurement outcome is random (50/50), no usable signal travels faster than light.",
      papers: [
        "• **[Bell Nonlocality (Brunner et al., 2014)](https://arxiv.org/abs/1303.2849)** — Comprehensive review of Bell inequalities and quantum entanglement."
      ]
    },
    {
      match: /zk-snark|zero-knowledge|succinct|arithmetic circuit|quadratic arithmetic|elliptic curve|prover|verifier|witness|polynomial|entropy/i,
      title: "Zero-Knowledge Cryptographic Proofs (zk-SNARKs)",
      plain: "A **zk-SNARK** is a mathematical way to prove that you know a secret (or did a calculation honestly) with near-100% certainty—without revealing a single clue about the secret itself, in a tiny digital receipt that takes milliseconds to verify.",
      analogy: "Think of **'Where's Waldo?'**. To prove you found Waldo without giving away his location, you place a huge sheet of cardboard over the poster with a tiny cutout window showing *only* Waldo's face.",
      background: "Zero-knowledge proofs allow privacy blockchains, digital IDs, and authentication systems to verify transactions or age requirements without exposing sensitive personal data.",
      mechanisms: "The computation is turned into a system of math equations (an arithmetic circuit), compressed into polynomials (a Quadratic Arithmetic Program), and checked at a random secret point using elliptic curve cryptography.",
      papers: [
        "• **[Pinocchio: Nearly Practical Verifiable Computation (Parno et al., 2013)](https://eprint.iacr.org/2013/279)** — Foundational paper introducing practical zk-SNARKs."
      ]
    },
    {
      match: /dcas9|cas9|crispr|krab|dnmt|cpg|methylation|histone|h3k9me3|heterochromatin|mitotic|phosphodiester|cleavage|epigenetic/i,
      title: "Epigenetic Gene Silencing (CRISPRoff / dCas9)",
      plain: "Instead of using CRISPR like molecular scissors to permanently cut DNA, **epigenetic CRISPR (`dCas9`)** places a chemical dimmer switch on a target gene—turning that gene off even as the cell divides, without cutting a single strand of DNA.",
      analogy: "Imagine your DNA is a master cookbook. Traditional CRISPR cuts a recipe page out with scissors. Epigenetic CRISPR leaves every page intact and simply puts a sticky note over a recipe that says *'Skip this recipe.'*",
      background: "By disabling Cas9's cutting blades and attaching natural chemical tags (`methylation`), researchers can safely and reversibly silence disease-causing genes without risking DNA repair errors.",
      mechanisms: "Catalytically dead Cas9 (dCas9) still uses guide RNA to find the exact DNA sequence, while attached KRAB and DNMT3A/3L proteins add methyl tags to CpG islands and pack histones tightly so RNA polymerase cannot read the gene.",
      papers: [
        "• **[Genome-wide programmable transcriptional memory by CRISPR-based epigenome editing (Nunez et al., Cell 2021)](https://pubmed.ncbi.nlm.nih.gov/33838111/)** — The landmark CRISPRoff paper."
      ]
    }
  ];

  function findDomainItem(text) {
    for (const item of DOMAIN_KNOWLEDGE) {
      if (item.match.test(text || '')) return item;
    }
    return null;
  }

  function buildInstantLaymanExplanation(rawText) {
    const clean = (rawText || '').trim();
    const item = findDomainItem(clean);
    if (item) {
      return [
        `**1. In Plain English (Layman's Terms):**`,
        `You highlighted: *"${clean.length > 130 ? clean.slice(0, 130) + '...' : clean}"*`,
        item.plain,
        ``,
        `**2. Intuitive Everyday Analogy:**`,
        item.analogy,
        ``,
        `**3. Important Background Information:**`,
        item.background,
        ``,
        `**4. Want to Dive Deeper?**`,
        `Do you have any follow-up questions about **${item.title}**, or is there anything else you'd like me to help with?`
      ].join('\n');
    }

    const words = clean.split(/\s+/).filter(Boolean);
    const keyTerms = words
      .map((w) => w.replace(/[^a-zA-Z0-9-]/g, ''))
      .filter((w) => w.length >= 4)
      .slice(0, 4);
    const focusPhrase = keyTerms.length > 0 ? keyTerms.join(', ') : clean.slice(0, 50);

    return [
      `**1. In Plain English (Layman's Terms):**`,
      `**"${clean.length > 120 ? clean.slice(0, 120) + '...' : clean}"** describes how the key factors here (**${focusPhrase}**) relate to one another so researchers can measure or predict how the system behaves without guesswork.`,
      ``,
      `**2. Intuitive Everyday Analogy:**`,
      `Think of **${focusPhrase}** like a graphic equalizer on a stereo or a contour map of a mountain range: instead of looking at a messy jumble of data all at once, it sorts the pattern by scale so you can immediately spot the main peaks and trends.`,
      ``,
      `**3. Important Background Information:**`,
      `In technical papers, terms like **${focusPhrase}** are used as shorthand for a standard measurement method. Once you know it is simply measuring how strong a pattern is across different scales, the surrounding equations and results become much easier to follow.`,
      ``,
      `**4. Want to Dive Deeper?**`,
      `Do you have any follow-up questions about **"${clean.length > 60 ? clean.slice(0, 60) + '...' : clean}"**, want links to papers on this topic, or have another question you'd like answered?`
    ].join('\n');
  }

  /**
   * Offline Fallback Responder (only used if both DeepSeek API and Cloud LLM are unreachable):
   * Handles paper/link requests, general unrelated questions, and contextual follow-ups
   * naturally in digestible language without locking the user into a repetitive template.
   */
  function buildInstantFollowUpReply(question, origHighlight) {
    const q = (question || '').trim();
    const qLower = q.toLowerCase();
    const baseHighlight = (origHighlight || currentHighlight || '').trim();
    const item = findDomainItem(baseHighlight) || findDomainItem(q);
    const searchTopic = baseHighlight || q;
    const encodedTopic = encodeURIComponent(searchTopic.slice(0, 80));

    // 1. User asks for links, papers, articles, or references
    if (qLower.includes('link') || qLower.includes('paper') || qLower.includes('article') || qLower.includes('source') || qLower.includes('study') || qLower.includes('read more')) {
      const specificPapers = item?.papers ? item.papers.join('\n') + '\n' : '';
      return [
        `Here are direct links to key papers and search repositories on **${searchTopic || 'this topic'}**, explained simply:`,
        ``,
        specificPapers +
          `• **[arXiv Preprints on "${searchTopic}"](https://arxiv.org/search/?query=${encodedTopic}&searchtype=all)** — Open-access research papers and review articles on arXiv.`,
        `• **[Google Scholar Papers on "${searchTopic}"](https://scholar.google.com/scholar?q=${encodedTopic})** — Highly cited foundational papers and introductory reviews.`,
        `• **[NASA ADS Astrophysics Archive for "${searchTopic}"](https://ui.adsabs.harvard.edu/search/q=${encodedTopic})** — Full-text astrophysics and cosmology literature index.`,
        ``,
        `Would you like me to summarize the main findings of any of these papers in plain English, or help with another question?`
      ].join('\n');
    }

    // 2. Check if the user is asking a general/unrelated question (math, coding, everyday question)
    if (qLower.includes('code') || qLower.includes('python') || qLower.includes('javascript') || qLower.includes('function')) {
      return `Sure! Here is a clean, easy-to-read example for **${q}**:\n\nWhen writing code for this, the easiest way to think about it is breaking the problem into three small steps: (1) take the input, (2) process each item with a simple rule, and (3) return the clean result. Let me know what language or specific inputs you want to use and I'll tailor it for you!`;
    }

    // 3. Contextual follow-up in simple, digestible vernacular
    if (item) {
      if (qLower.includes('how') || qLower.includes('why') || qLower.includes('work')) {
        return `${item.mechanisms}\n\nPut simply, ${item.plain.charAt(0).toLowerCase() + item.plain.slice(1)}\n\nLet me know if you want to explore the math behind it, see links to papers, or ask anything else!`;
      }
      return `${item.plain}\n\n**Intuitive way to picture it:** ${item.analogy}\n\n**More details:** ${item.mechanisms}\n\nWhat else can I help you with?`;
    }

    return `In simple terms regarding **"${q}"**${baseHighlight ? ` (building on **"$` + `{baseHighlight.slice(0, 60)}"**)` : ''}:\n\nThe core idea is straightforward: instead of getting bogged down in dense jargon, break it down into what is being measured (the input) and what pattern comes out (the output). You can also check [arXiv papers on this topic](https://arxiv.org/search/?query=${encodedTopic}&searchtype=all) or [Google Scholar](https://scholar.google.com/scholar?q=${encodedTopic}) for deeper reading.\n\nWhat else would you like to ask or explore?`;
  }

  function requestChatFromExtension(payload, isInitial, userQuestion = '') {
    return new Promise((resolve) => {
      let settled = false;
      const activeText = sessionHighlight || currentHighlight;
      // Give live LLM calls up to 22 seconds so real responses are never prematurely cut off!
      const timer = setTimeout(() => {
        if (!settled) {
          settled = true;
          resolve({
            reply: isInitial
              ? buildInstantLaymanExplanation(activeText)
              : buildInstantFollowUpReply(userQuestion, activeText),
            source: 'instant-fallback'
          });
        }
      }, 22000);

      try {
        chrome.runtime.sendMessage(payload, (res) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          if (!chrome.runtime.lastError && res && res.ok && res.data?.reply) {
            resolve({ reply: res.data.reply, source: res.data.source || 'api' });
          } else {
            resolve({
              reply: isInitial
                ? buildInstantLaymanExplanation(activeText)
                : buildInstantFollowUpReply(userQuestion, activeText),
              source: 'instant-fallback'
            });
          }
        });
      } catch (_) {
        if (!settled) {
          settled = true;
          clearTimeout(timer);
          resolve({
            reply: isInitial
              ? buildInstantLaymanExplanation(activeText)
              : buildInstantFollowUpReply(userQuestion, activeText),
            source: 'instant-fallback'
          });
        }
      }
    });
  }

  function getAdaptiveBoxRect(isRightSide) {
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const marginX = Math.round(Math.max(10, Math.min(24, vw * 0.015)));
    const marginY = Math.round(Math.max(10, Math.min(24, vh * 0.02)));

    let width;
    if (vw < 500) {
      width = vw - marginX * 2;
    } else {
      width = Math.round(Math.min(Math.max(vw * 0.28, 270), Math.min(440, vw - marginX * 2)));
    }
    const left = isRightSide ? (vw - marginX - width) : marginX;
    const right = left + width;
    const top = marginY;
    const bottom = vh - marginY;
    return { left, right, top, bottom, width, height: bottom - top };
  }

  function applyFluidDockedStyles(isRightSide) {
    if (!chatSidebar) return;
    chatSidebar.classList.toggle('ds-dock-right', isRightSide);
    chatSidebar.classList.toggle('ds-dock-left', !isRightSide);
    chatSidebar.style.top = '2vh';
    chatSidebar.style.bottom = '2vh';
    chatSidebar.style.height = 'auto';
    chatSidebar.style.width = 'clamp(270px, 28vw, calc(100vw - 3vw))';
    if (isRightSide) {
      chatSidebar.style.right = '1.5vw';
      chatSidebar.style.left = 'auto';
    } else {
      chatSidebar.style.left = '1.5vw';
      chatSidebar.style.right = 'auto';
    }
    chatSidebar.style.opacity = '1';
    chatSidebar.style.pointerEvents = 'auto';
  }

  let isAtRest = true;
  let isSwooping = false;
  let swoopAnimId = null;
  let lastSwoopPath = null; // Stores { startX, startY, ctrlX, ctrlY, endX, endY } for exact reverse path
  let brainCurrentPos = { x: 0, y: 0 };
  let customIdlePos = null; // Set when user double-clicks a location to relocate the idle brain
  let sendHomeBtn = null;
  let lastMouseDownTime = 0;

  function getInitialHomePosition() {
    return {
      x: Math.max(16, window.innerWidth - ICON_SIZE - 20),
      y: 18
    };
  }

  function getRestPosition() {
    if (customIdlePos) {
      return {
        x: Math.min(window.innerWidth - ICON_SIZE - 12, Math.max(12, customIdlePos.x)),
        y: Math.min(window.innerHeight - ICON_SIZE - 12, Math.max(12, customIdlePos.y))
      };
    }
    if (isMinimized) {
      return getActiveMinimizeTargetPos();
    }
    return getInitialHomePosition();
  }

  function hideSendHomeButton() {
    if (sendHomeBtn) {
      sendHomeBtn.classList.remove('ds-visible');
    }
  }

  function toggleSendHomeButton() {
    if (!sendHomeBtn) return;
    sendHomeBtn.classList.toggle('ds-visible');
  }

  function sendBrainToInitialHome() {
    hideSendHomeButton();
    customIdlePos = null;
    minimizedCustomPos = null;
    currentHighlight = '';
    const home = getInitialHomePosition();
    isAtRest = true;
    animateBrainSwoop(home.x, home.y, false);
  }

  function computeNonlinearSwoopControlPoint(x0, y0, x2, y2) {
    // Non-linear swooping arc: dips gracefully below the straight line so it swoops down and curves in
    const midX = (x0 + x2) / 2;
    const midY = (y0 + y2) / 2;
    const dx = x2 - x0;
    const dy = y2 - y0;
    const ctrlX = midX + dx * 0.18;
    const ctrlY = Math.max(y0, y2) + Math.min(160, Math.max(65, Math.abs(dy) * 0.32 + Math.abs(dx) * 0.14));
    return { ctrlX, ctrlY };
  }

  function evalQuadraticBezier(u, x0, y0, cx, cy, x2, y2) {
    const inv = 1 - u;
    const x = inv * inv * x0 + 2 * inv * u * cx + u * u * x2;
    const y = inv * inv * y0 + 2 * inv * u * cy + u * u * y2;
    return { x, y };
  }

  function easeInOutCubic(t) {
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }

  /**
   * Animates the 3D brain along a non-linear quadratic Bezier swoop curve.
   * When returning to the top-right corner (`reverse === true`), it follows the exact
   * same curve (`lastSwoopPath`) in reverse (u: 1 -> 0).
   */
  function animateBrainSwoop(targetX, targetY, reverse = false, onDone = null) {
    ensureElements();
    if (swoopAnimId) {
      cancelAnimationFrame(swoopAnimId);
      swoopAnimId = null;
    }

    let pathObj;
    if (reverse && lastSwoopPath) {
      const rest = getRestPosition();
      pathObj = {
        startX: rest.x,
        startY: rest.y,
        ctrlX: lastSwoopPath.ctrlX,
        ctrlY: lastSwoopPath.ctrlY,
        endX: brainCurrentPos.x || lastSwoopPath.endX,
        endY: brainCurrentPos.y || lastSwoopPath.endY
      };
    } else {
      const startX = brainCurrentPos.x || getRestPosition().x;
      const startY = brainCurrentPos.y || getRestPosition().y;
      const { ctrlX, ctrlY } = computeNonlinearSwoopControlPoint(startX, startY, targetX, targetY);
      pathObj = { startX, startY, ctrlX, ctrlY, endX: targetX, endY: targetY };
      lastSwoopPath = pathObj;
    }

    isSwooping = true;
    floatingIcon.style.display = 'block';
    const duration = 440;
    const startTime = performance.now();

    function step(now) {
      const raw = Math.min(1, (now - startTime) / duration);
      const eased = easeInOutCubic(raw);
      const u = reverse ? (1 - eased) : eased;

      const pt = evalQuadraticBezier(
        u,
        pathObj.startX,
        pathObj.startY,
        pathObj.ctrlX,
        pathObj.ctrlY,
        pathObj.endX,
        pathObj.endY
      );

      brainCurrentPos = { x: pt.x, y: pt.y };
      floatingIcon.style.left = `${pt.x.toFixed(1)}px`;
      floatingIcon.style.top = `${pt.y.toFixed(1)}px`;

      // Subtle dynamic banking tilt during the swoop flight
      const bankDeg = Math.sin(raw * Math.PI) * (reverse ? 10 : -10);
      floatingIcon.style.transform = raw < 1 ? `rotate(${bankDeg.toFixed(1)}deg)` : 'none';

      if (raw < 1) {
        swoopAnimId = requestAnimationFrame(step);
      } else {
        swoopAnimId = null;
        isSwooping = false;
        floatingIcon.style.transform = 'none';
        if (onDone) onDone();
      }
    }

    swoopAnimId = requestAnimationFrame(step);
  }

  function ensureElements() {
    if (!IS_TOP_FRAME) return;
    if (!floatingIcon) {
      floatingIcon = document.createElement('div');
      floatingIcon.id = 'ds-layman-floating-icon';
      const rest = getRestPosition();
      brainCurrentPos = { x: rest.x, y: rest.y };
      floatingIcon.style.left = `${rest.x}px`;
      floatingIcon.style.top = `${rest.y}px`;
      floatingIcon.style.display = 'block';
      floatingIcon.title = "Highlight text on the page, then click the 3D brain to explain!";
      floatingIcon.innerHTML = `
        <button type="button" id="ds-send-home-btn" title="Return brain to upper-right corner">Send Home</button>
        <div class="ds-brain-idle-wrap">
          <div class="ds-brain-rotator">
            <img class="ds-layer-img ds-brain-base" src="${BRAIN_URI}" alt="" />
            <img class="ds-layer-img ds-brain-eyes" src="${BRAIN_EYES_URI}" alt="" />
            <img class="ds-layer-img ds-sleep-mask" src="${SLEEP_MASK_URI}" alt="" />
            <img class="ds-layer-img ds-notes-glasses" src="${GLASSES_URI}" alt="" />
          </div>
          <img class="ds-layer-img ds-notes-pad-base" src="${NOTEPAD_BASE_URI}" alt="" />
          <img class="ds-layer-img ds-notes-lines" src="${NOTEPAD_LINES_URI}" alt="" />
          <img class="ds-layer-img ds-notes-flip-sheet" src="${NOTEPAD_FLIP_URI}" alt="" />
          <img class="ds-layer-img ds-notes-pencil" src="${PENCIL_URI}" alt="" />
        </div>
        <img class="ds-layer-img ds-sleep-z ds-sleep-z1" src="${SLEEP_Z1_URI}" alt="" />
        <img class="ds-layer-img ds-sleep-z ds-sleep-z2" src="${SLEEP_Z2_URI}" alt="" />
        <img class="ds-layer-img ds-bolt ds-bolt-left" src="${BOLT_LEFT_URI}" alt="" />
        <img class="ds-layer-img ds-bolt ds-bolt-center" src="${BOLT_CENTER_URI}" alt="" />
        <img class="ds-layer-img ds-bolt ds-bolt-right" src="${BOLT_RIGHT_URI}" alt="" />
      `;
      sendHomeBtn = floatingIcon.querySelector('#ds-send-home-btn');
      sendHomeBtn.addEventListener('mousedown', (e) => {
        e.preventDefault();
        e.stopPropagation();
        sendBrainToInitialHome();
      });
      floatingIcon.addEventListener('mousedown', (e) => {
        if (sendHomeBtn && sendHomeBtn.contains(e.target)) return;
        e.preventDefault();
        e.stopPropagation();
        // 1. If a new piece of text is currently highlighted, explain the new highlight
        if (currentHighlight && currentHighlight.length > 1) {
          hideSendHomeButton();
          isMinimized = false;
          minimizedCustomPos = null;
          triggerThinkingThenTransition();
        } else if (isMinimized && sessionMessages.length > 0) {
          // 2. If the chat box was minimized, clicking the brain reopens the chat box with the preserved session!
          hideSendHomeButton();
          triggerRestoreFromMinimizeTransition();
        } else {
          // 3. Otherwise, toggle the "Send Home" button above the idle brain
          toggleSendHomeButton();
        }
      });
      (document.body || document.documentElement).appendChild(floatingIcon);
    }

    if (!curveOverlay) {
      curveOverlay = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      curveOverlay.id = 'ds-layman-curve-overlay';
      curveOverlay.innerHTML = `
        <defs>
          <linearGradient id="ds-exp-fill-grad" x1="0%" y1="100%" x2="100%" y2="0%">
            <stop offset="0%" stop-color="rgba(230, 207, 165, 0.38)" />
            <stop offset="55%" stop-color="rgba(238, 221, 190, 0.24)" />
            <stop offset="100%" stop-color="rgba(223, 197, 153, 0.42)" />
          </linearGradient>
          <filter id="ds-liquid-glass-refract" x="-10%" y="-10%" width="120%" height="120%" color-interpolation-filters="sRGB">
            <feTurbulence type="fractalNoise" baseFrequency="0.012 0.02" numOctaves="2" seed="7" result="liquidNoise" />
            <feGaussianBlur in="liquidNoise" stdDeviation="3" result="smoothLiquid" />
            <feDisplacementMap in="SourceGraphic" in2="smoothLiquid" scale="9" xChannelSelector="R" yChannelSelector="G" />
          </filter>
        </defs>
        <path id="ds-exp-area-path" fill="url(#ds-exp-fill-grad)" d="" />
        <path id="ds-exp-upper-stroke" fill="none" stroke="#e6cfa5" stroke-width="3" stroke-linecap="round" d="" />
        <path id="ds-exp-lower-stroke" fill="none" stroke="#e6cfa5" stroke-width="3" stroke-linecap="round" d="" />
      `;
      (document.body || document.documentElement).appendChild(curveOverlay);
    }

    if (!chatSidebar) {
      chatSidebar = document.createElement('aside');
      chatSidebar.id = 'ds-layman-chat-sidebar';
      chatSidebar.innerHTML = `
        <div class="ds-chat-header">
          <div class="ds-chat-brand">
            <img class="ds-chat-brand-icon" src="${FULL_ICON_URI}" alt="" />
            <div>
              <h3 class="ds-chat-title" id="ds-header-title-text">Layman's Intuition AI</h3>
              <p class="ds-chat-subtitle" id="ds-header-subtitle-text">DeepSeek LLM • Session Context Active</p>
            </div>
          </div>
          <div class="ds-chat-header-actions">
            <!-- Notes Button (Replicating Image 2: Rounded Document with 3 Lines + Overlapping Diagonal Pencil) -->
            <button type="button" class="ds-chat-notes-btn" id="ds-chat-notes-btn" title="Open Saved Notes">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none;">
                <path d="M19 11V6a3 3 0 0 0-3-3H7a3 3 0 0 0-3 3v12a3 3 0 0 0 3 3h9a3 3 0 0 0 3-3v-1" />
                <line x1="8" y1="8" x2="15" y2="8" stroke-width="2.3" />
                <line x1="8" y1="12" x2="15" y2="12" stroke-width="2.3" />
                <line x1="8" y1="16" x2="12" y2="16" stroke-width="2.3" />
                <path d="M18.2 11.8a1.6 1.6 0 0 1 2.3 2.3L15 19.6l-3 .7.7-3 5.5-5.5z" fill="rgba(255,255,255,0.85)" />
              </svg>
            </button>
            <!-- Back Arrow Button (Shown in Notes View beside Minimize Button to Rewind Scroll Back to Chat) -->
            <button type="button" class="ds-notes-back-btn" id="ds-notes-back-btn" title="Back to Chat" style="display:none !important;">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none;">
                <line x1="19" y1="12" x2="5" y2="12"></line>
                <polyline points="12 19 5 12 12 5"></polyline>
              </svg>
            </button>
            <button type="button" class="ds-chat-minimize-btn" id="ds-chat-minimize" title="Minimize chat (preserves session)">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none;">
                <polyline points="6 9 12 15 18 9"></polyline>
              </svg>
            </button>
            <button type="button" class="ds-chat-close-btn" id="ds-chat-close" title="Exit chat & clear session">✕</button>
          </div>
        </div>
        <div id="ds-chat-body-wrap">
          <button type="button" id="ds-add-to-notes-btn" title="Save highlighted text to your Notepad">Add to Notes</button>
          <div class="ds-highlighted-quote" id="ds-quote-box"></div>
          <div class="ds-chat-messages" id="ds-messages-list"></div>
          <form class="ds-chat-input-area" id="ds-chat-form">
            <input type="text" class="ds-chat-input" id="ds-chat-input" placeholder="Ask a follow-up or any question..." autocomplete="off" />
            <button type="submit" class="ds-chat-send-btn">Ask</button>
          </form>
          <!-- Unwinding Scroll Lined Notepad Panel -->
          <div id="ds-notepad-scroll-panel">
            <div class="ds-lined-notepad" id="ds-lined-notepad-list"></div>
            <div class="ds-scroll-roller"></div>
          </div>
        </div>
      `;
      (document.body || document.documentElement).appendChild(chatSidebar);

      ['mousedown', 'mouseup', 'click', 'pointerdown', 'pointerup', 'wheel', 'keydown', 'keyup'].forEach((evtName) => {
        chatSidebar.addEventListener(evtName, (e) => {
          e.stopPropagation();
        });
      });

      const addToNotesBtn = chatSidebar.querySelector('#ds-add-to-notes-btn');
      const notesOpenBtn = chatSidebar.querySelector('#ds-chat-notes-btn');
      const notesBackBtn = chatSidebar.querySelector('#ds-notes-back-btn');

      addToNotesBtn.addEventListener('mousedown', (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (pendingChatNoteText) {
          addNoteToNotepad(pendingChatNoteText);
          pendingChatNoteText = '';
          addToNotesBtn.textContent = '✓ Saved!';
          setTimeout(() => {
            addToNotesBtn.classList.remove('ds-visible');
            addToNotesBtn.textContent = 'Add to Notes';
          }, 420);
          try {
            window.getSelection().removeAllRanges();
          } catch (_) {}
        }
      });

      notesOpenBtn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        animateNotepadScroll(true);
      });

      notesBackBtn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        animateNotepadScroll(false);
      });

      // Detect when the user highlights text INSIDE the chat box to display the "Add to Notes" Liquid Glass bubble
      chatSidebar.addEventListener('mouseup', (e) => {
        if (addToNotesBtn.contains(e.target)) return;
        setTimeout(() => {
          checkChatBoxInternalHighlight();
        }, 25);
      });

      chatSidebar.addEventListener('mousedown', (e) => {
        if (!addToNotesBtn.contains(e.target)) {
          addToNotesBtn.classList.remove('ds-visible');
        }
      });

      chatSidebar.querySelector('#ds-chat-minimize').addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        triggerMinimizeTransition();
      });

      chatSidebar.querySelector('#ds-chat-close').addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        triggerCloseTransition();
      });

      chatSidebar.querySelector('#ds-chat-form').addEventListener('submit', (e) => {
        e.preventDefault();
        e.stopPropagation();
        const input = chatSidebar.querySelector('#ds-chat-input');
        const text = input.value.trim();
        if (!text) return;
        input.value = '';
        handleFollowUpQuestion(text);
      });
    }
  }

  let savedNotes = [];
  let pendingChatNoteText = '';
  let isNotesViewOpen = false;
  let isScrollAnimating = false;

  // Load any previously saved notes from chrome.storage.local
  try {
    if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
      chrome.storage.local.get(['dsLaymanSavedNotes'], (res) => {
        if (res && Array.isArray(res.dsLaymanSavedNotes)) {
          savedNotes = res.dsLaymanSavedNotes;
        }
      });
    }
  } catch (_) {}

  function persistSavedNotes() {
    try {
      if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
        chrome.storage.local.set({ dsLaymanSavedNotes: savedNotes });
      }
    } catch (_) {}
  }

  function renderNotepadLines() {
    if (!chatSidebar) return;
    const listEl = chatSidebar.querySelector('#ds-lined-notepad-list');
    if (!listEl) return;
    listEl.innerHTML = '';

    if (savedNotes.length === 0) {
      const hint = document.createElement('div');
      hint.className = 'ds-note-empty-hint';
      hint.textContent = 'Highlight any text in the chat box and click "Add to Notes" to save notes here...';
      listEl.appendChild(hint);
      return;
    }

    savedNotes.forEach((noteText, idx) => {
      const row = document.createElement('div');
      row.className = 'ds-note-item';
      const bullet = document.createElement('span');
      bullet.className = 'ds-note-bullet';
      bullet.textContent = '•';
      const span = document.createElement('span');
      span.textContent = noteText;
      const delBtn = document.createElement('button');
      delBtn.type = 'button';
      delBtn.className = 'ds-note-delete-btn';
      delBtn.title = 'Delete note';
      delBtn.textContent = '✕';
      delBtn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        savedNotes.splice(idx, 1);
        persistSavedNotes();
        renderNotepadLines();
      });
      row.appendChild(bullet);
      row.appendChild(span);
      row.appendChild(delBtn);
      listEl.appendChild(row);
    });
  }

  function addNoteToNotepad(text) {
    const cleaned = String(text || '').trim();
    if (!cleaned) return;
    savedNotes.push(cleaned);
    persistSavedNotes();
    renderNotepadLines();
  }

  function checkChatBoxInternalHighlight() {
    if (!chatSidebar || isNotesViewOpen) return;
    const addBtn = chatSidebar.querySelector('#ds-add-to-notes-btn');
    if (!addBtn) return;

    const sel = window.getSelection();
    const text = sel && !sel.isCollapsed ? sel.toString().trim() : '';
    if (text.length > 1 && sel.anchorNode && chatSidebar.contains(sel.anchorNode)) {
      try {
        const range = sel.getRangeAt(0);
        const rect = range.getBoundingClientRect();
        const bodyWrap = chatSidebar.querySelector('#ds-chat-body-wrap');
        const wrapRect = bodyWrap.getBoundingClientRect();

        pendingChatNoteText = text;
        const relCenterX = Math.min(wrapRect.width - 64, Math.max(64, (rect.left + rect.right) / 2 - wrapRect.left));
        const relTopY = Math.max(8, rect.top - wrapRect.top - 36);

        addBtn.style.left = `${relCenterX.toFixed(1)}px`;
        addBtn.style.top = `${relTopY.toFixed(1)}px`;
        addBtn.textContent = 'Add to Notes';
        addBtn.classList.add('ds-visible');
        return;
      } catch (_) {}
    }
    pendingChatNoteText = '';
    addBtn.classList.remove('ds-visible');
  }

  /**
   * Unwinding Scroll Animation (Top -> Bottom when opening Notes; Bottom -> Top in reverse when clicking Back Arrow)
   */
  function animateNotepadScroll(openNotes) {
    if (!chatSidebar || isScrollAnimating) return;
    if (openNotes === isNotesViewOpen) return;
    isScrollAnimating = true;

    const panel = chatSidebar.querySelector('#ds-notepad-scroll-panel');
    const notesOpenBtn = chatSidebar.querySelector('#ds-chat-notes-btn');
    const notesBackBtn = chatSidebar.querySelector('#ds-notes-back-btn');
    const titleEl = chatSidebar.querySelector('#ds-header-title-text');
    const subtitleEl = chatSidebar.querySelector('#ds-header-subtitle-text');
    const addBtn = chatSidebar.querySelector('#ds-add-to-notes-btn');

    if (addBtn) addBtn.classList.remove('ds-visible');

    if (openNotes) {
      renderNotepadLines();
      panel.style.display = 'flex';
      panel.style.height = '0%';
      notesOpenBtn.style.setProperty('display', 'none', 'important');
      notesBackBtn.style.setProperty('display', 'flex', 'important');
      titleEl.textContent = 'Session Notepad';
      subtitleEl.textContent = `${savedNotes.length} Saved Note${savedNotes.length === 1 ? '' : 's'} • Lined View`;
    } else {
      notesBackBtn.style.setProperty('display', 'none', 'important');
      notesOpenBtn.style.setProperty('display', 'flex', 'important');
      titleEl.textContent = "Layman's Intuition AI";
      subtitleEl.textContent = 'DeepSeek LLM • Session Context Active';
    }

    const duration = 320;
    const startTime = performance.now();

    function step(now) {
      const raw = Math.min(1, (now - startTime) / duration);
      const eased = easeInOutCubic(raw);
      const pct = openNotes ? (eased * 100) : ((1 - eased) * 100);
      panel.style.height = `${pct.toFixed(2)}%`;

      if (raw < 1) {
        requestAnimationFrame(step);
      } else {
        isNotesViewOpen = openNotes;
        isScrollAnimating = false;
        if (!openNotes) {
          panel.style.display = 'none';
          panel.style.height = '0%';
        } else {
          panel.style.height = '100%';
        }
      }
    }

    requestAnimationFrame(step);
  }

  function getExponentialPoint(u, startX, startY, endX, endY, k = 2.6) {
    const x = startX + (endX - startX) * u;
    const expFactor = (Math.exp(k * u) - 1) / (Math.exp(k) - 1);
    const y = startY + (endY - startY) * expFactor;
    return { x, y };
  }

  function runExponentialCurveAnimation(direction, onComplete) {
    ensureElements();
    isAnimating = true;

    const areaPath = curveOverlay.querySelector('#ds-exp-area-path');
    const upperStroke = curveOverlay.querySelector('#ds-exp-upper-stroke');
    const lowerStroke = curveOverlay.querySelector('#ds-exp-lower-stroke');

    const screenMidX = window.innerWidth / 2;
    const isRightSide = direction === 'forward' ? (iconOrigin.x >= screenMidX) : (currentDockSide === 'right');
    currentDockSide = isRightSide ? 'right' : 'left';

    const targetBox = getAdaptiveBoxRect(isRightSide);
    const finalLeft = targetBox.left;
    const finalRight = targetBox.right;
    const finalTop = targetBox.top;
    const finalBottom = targetBox.bottom;

    const initLeft = iconOrigin.x - ICON_RADIUS;
    const initRight = iconOrigin.x + ICON_RADIUS;
    const initTop = iconOrigin.y - ICON_RADIUS;
    const initBottom = iconOrigin.y + ICON_RADIUS;

    const proximity = Math.min(1, Math.max(0, Math.abs(iconOrigin.x - screenMidX) / Math.max(1, screenMidX)));
    const steepnessK = 2.2 + 3.6 * proximity;

    const startCornerX = isRightSide ? Math.min(initLeft, finalLeft - 14) : Math.max(initRight, finalRight + 14);
    const targetCornerX = isRightSide ? finalLeft : finalRight;

    floatingIcon.classList.remove('ds-thinking', 'ds-sleeping', 'ds-notes-minimized');
    floatingIcon.style.display = 'none';
    floatingIcon.style.transform = 'none';

    chatSidebar.style.transition = 'none';
    chatSidebar.style.opacity = '1';
    chatSidebar.style.pointerEvents = direction === 'forward' ? 'auto' : 'none';
    chatSidebar.style.transform = 'none';
    chatSidebar.style.right = 'auto';
    chatSidebar.style.bottom = 'auto';
    if (direction === 'forward') {
      chatSidebar.classList.add('ds-open');
    }

    const duration = 180;
    const startTime = performance.now();

    function frame(now) {
      const rawElapsed = Math.min(1, (now - startTime) / duration);
      const t = direction === 'forward' ? rawElapsed : 1 - rawElapsed;
      const expFactor = (Math.exp(steepnessK * t) - 1) / (Math.exp(steepnessK) - 1);

      const curLeft = initLeft + (finalLeft - initLeft) * t;
      const curRight = initRight + (finalRight - initRight) * t;
      const curTop = initTop + (finalTop - initTop) * expFactor;
      const curBottom = initBottom + (finalBottom - initBottom) * expFactor;
      const curRadius = 16 + (18 - 16) * t;

      chatSidebar.style.left = `${curLeft.toFixed(1)}px`;
      chatSidebar.style.top = `${curTop.toFixed(1)}px`;
      chatSidebar.style.width = `${Math.max(ICON_SIZE, curRight - curLeft).toFixed(1)}px`;
      chatSidebar.style.height = `${Math.max(ICON_SIZE, curBottom - curTop).toFixed(1)}px`;
      chatSidebar.style.borderRadius = `${curRadius.toFixed(1)}px`;

      const steps = 32;
      const maxStep = Math.max(1, Math.round(steps * t));
      const upperPts = [];
      const lowerPts = [];

      for (let i = 0; i <= maxStep; i++) {
        const u = (i / steps) * t;
        upperPts.push(getExponentialPoint(u, startCornerX, initTop, targetCornerX, finalTop, steepnessK));
        lowerPts.push(getExponentialPoint(u, startCornerX, initBottom, targetCornerX, finalBottom, steepnessK));
      }

      if (upperPts.length > 1 && t > 0.01 && t < 0.99) {
        const upperCmd = upperPts.map((p, idx) => `${idx === 0 ? 'M' : 'L'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');
        const lowerCmd = lowerPts.map((p, idx) => `${idx === 0 ? 'M' : 'L'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');
        const lowerRevCmd = [...lowerPts].reverse().map((p) => `L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');

        upperStroke.setAttribute('d', upperCmd);
        lowerStroke.setAttribute('d', lowerCmd);
        areaPath.setAttribute('d', `${upperCmd} ${lowerRevCmd} Z`);
      } else {
        upperStroke.setAttribute('d', '');
        lowerStroke.setAttribute('d', '');
        areaPath.setAttribute('d', '');
      }

      if (rawElapsed < 1) {
        requestAnimationFrame(frame);
      } else {
        upperStroke.setAttribute('d', '');
        lowerStroke.setAttribute('d', '');
        areaPath.setAttribute('d', '');

        if (direction === 'forward') {
          chatSidebar.classList.add('ds-open');
          applyFluidDockedStyles(isRightSide);
        } else {
          chatSidebar.classList.remove('ds-open');
          chatSidebar.style.opacity = '0';
          chatSidebar.style.pointerEvents = 'none';
        }
        isAnimating = false;
        if (onComplete) onComplete();
      }
    }

    requestAnimationFrame(frame);
  }

  async function triggerThinkingThenTransition() {
    if (isAnimating || isThinking || !currentHighlight) return;
    isThinking = true;

    sessionHighlight = currentHighlight;

    floatingIcon.style.display = 'block';
    floatingIcon.classList.add('ds-thinking');
    resetBrainEyeAndBodyTracking();

    sessionMessages = [
      {
        role: 'system',
        content: buildSessionSystemPrompt()
      },
      {
        role: 'user',
        content: `Please explain the following highlighted text in layman's terms, give an intuitive everyday analogy, provide important background information, and ask if I have any follow-up questions:\n\n"${sessionHighlight}"`
      }
    ];

    const [result] = await Promise.all([
      requestChatFromExtension(
        {
          type: 'DEEPSEEK_CHAT_REQUEST',
          highlightedText: sessionHighlight,
          messages: sessionMessages
        },
        true
      ),
      new Promise((r) => setTimeout(r, 950))
    ]);

    isThinking = false;
    floatingIcon.classList.remove('ds-thinking', 'ds-sleeping', 'ds-notes-minimized');

    ensureElements();
    const quoteBox = chatSidebar.querySelector('#ds-quote-box');
    const list = chatSidebar.querySelector('#ds-messages-list');
    quoteBox.textContent = `"${sessionHighlight}"`;
    list.innerHTML = '';

    sessionMessages.push({ role: 'assistant', content: result.reply });
    appendMessage('assistant', result.reply);

    runExponentialCurveAnimation('forward', () => {
      floatingIcon.style.display = 'none';
      chatSidebar.classList.add('ds-open');
      chatSidebar.style.pointerEvents = 'auto';
      isChatOpen = true;
    });
  }

  /**
   * When the chat box is closed:
   * 1. Reverse the chat-box-to-icon transition back to the highlighted text position.
   * 2. If highlighted text is no longer selected, make the 3D brain follow the exact same
   *    non-linear swoop path back to the top-right corner where it remains idle!
   */
  function getMinimizedCornerPosition(side) {
    if (side === 'left') {
      return { x: 20, y: 18 };
    }
    return {
      x: Math.max(16, window.innerWidth - ICON_SIZE - 20),
      y: 18
    };
  }

  /**
   * Returns the target position for Minimize / Restore:
   * - On first minimization (when the user hasn't moved the minimized icon via triple-click),
   *   returns the top-left or top-right corner depending on which side the chat box was opened on.
   * - If the user moved the minimized icon via triple-click (`minimizedCustomPos`), returns that
   *   exact moved position so reopening and subsequent minimizations converge to/from that spot!
   */
  function getActiveMinimizeTargetPos() {
    if (minimizedCustomPos) {
      return {
        x: Math.min(window.innerWidth - ICON_SIZE - 12, Math.max(12, minimizedCustomPos.x)),
        y: Math.min(window.innerHeight - ICON_SIZE - 12, Math.max(12, minimizedCustomPos.y))
      };
    }
    return getMinimizedCornerPosition(minimizedCornerSide);
  }

  /**
   * Collapsing / Expanding Transition for Minimize & Restore:
   * Shrinks the chat box from all points converging directly into the target brain icon position
   * (either the initial top-left/top-right corner, or the custom position the user triple-clicked
   * to move the brain to while minimized), preserving the chat session!
   */
  function runMinimizeOrRestoreAnimation(direction, onComplete) {
    ensureElements();
    isAnimating = true;

    const areaPath = curveOverlay.querySelector('#ds-exp-area-path');
    const upperStroke = curveOverlay.querySelector('#ds-exp-upper-stroke');
    const lowerStroke = curveOverlay.querySelector('#ds-exp-lower-stroke');

    const isRightSide = (currentDockSide === 'right');
    const cornerPos = getActiveMinimizeTargetPos();
    const cornerLeft = cornerPos.x;
    const cornerTop = cornerPos.y;
    const cornerRight = cornerLeft + ICON_SIZE;
    const cornerBottom = cornerTop + ICON_SIZE;
    const cornerCenterX = cornerLeft + ICON_RADIUS;
    const cornerCenterY = cornerTop + ICON_RADIUS;

    const targetBox = getAdaptiveBoxRect(isRightSide);
    const fullLeft = targetBox.left;
    const fullRight = targetBox.right;
    const fullTop = targetBox.top;
    const fullBottom = targetBox.bottom;

    floatingIcon.classList.remove('ds-thinking', 'ds-sleeping', 'ds-notes-minimized');
    floatingIcon.style.display = 'none';
    floatingIcon.style.transform = 'none';

    chatSidebar.style.transition = 'none';
    chatSidebar.style.opacity = '1';
    chatSidebar.style.pointerEvents = direction === 'restore' ? 'auto' : 'none';
    chatSidebar.style.transform = 'none';
    chatSidebar.style.right = 'auto';
    chatSidebar.style.bottom = 'auto';
    if (direction === 'restore') {
      chatSidebar.classList.add('ds-open');
    }

    const duration = 210;
    const startTime = performance.now();

    function frame(now) {
      const rawElapsed = Math.min(1, (now - startTime) / duration);
      const eased = easeInOutCubic(rawElapsed);
      const t = direction === 'restore' ? eased : (1 - eased);

      const curLeft = cornerLeft + (fullLeft - cornerLeft) * t;
      const curRight = cornerRight + (fullRight - cornerRight) * t;
      const curTop = cornerTop + (fullTop - cornerTop) * t;
      const curBottom = cornerBottom + (fullBottom - cornerBottom) * t;
      const curRadius = 16 + (24 - 16) * t;

      chatSidebar.style.left = `${curLeft.toFixed(1)}px`;
      chatSidebar.style.top = `${curTop.toFixed(1)}px`;
      chatSidebar.style.width = `${Math.max(ICON_SIZE, curRight - curLeft).toFixed(1)}px`;
      chatSidebar.style.height = `${Math.max(ICON_SIZE, curBottom - curTop).toFixed(1)}px`;
      chatSidebar.style.borderRadius = `${curRadius.toFixed(1)}px`;

      // Draw converging projection lines from the chat box's corners into the top corner brain icon
      if (t > 0.02 && t < 0.98) {
        const outerX = isRightSide ? curLeft : curRight;
        const innerX = isRightSide ? curRight : curLeft;
        const topLine = `M ${outerX.toFixed(1)} ${curTop.toFixed(1)} L ${cornerCenterX.toFixed(1)} ${cornerCenterY.toFixed(1)}`;
        const diagLine = `M ${outerX.toFixed(1)} ${curBottom.toFixed(1)} L ${cornerCenterX.toFixed(1)} ${cornerCenterY.toFixed(1)} L ${innerX.toFixed(1)} ${curBottom.toFixed(1)}`;
        const polyArea = `M ${outerX.toFixed(1)} ${curTop.toFixed(1)} L ${outerX.toFixed(1)} ${curBottom.toFixed(1)} L ${innerX.toFixed(1)} ${curBottom.toFixed(1)} L ${cornerCenterX.toFixed(1)} ${cornerCenterY.toFixed(1)} Z`;

        upperStroke.setAttribute('d', topLine);
        lowerStroke.setAttribute('d', diagLine);
        areaPath.setAttribute('d', polyArea);
      } else {
        upperStroke.setAttribute('d', '');
        lowerStroke.setAttribute('d', '');
        areaPath.setAttribute('d', '');
      }

      if (rawElapsed < 1) {
        requestAnimationFrame(frame);
      } else {
        upperStroke.setAttribute('d', '');
        lowerStroke.setAttribute('d', '');
        areaPath.setAttribute('d', '');

        if (direction === 'restore') {
          chatSidebar.classList.add('ds-open');
          applyFluidDockedStyles(isRightSide);
        } else {
          chatSidebar.classList.remove('ds-open');
          chatSidebar.style.opacity = '0';
          chatSidebar.style.pointerEvents = 'none';
        }
        isAnimating = false;
        if (onComplete) onComplete();
      }
    }

    requestAnimationFrame(frame);
  }

  function triggerMinimizeTransition() {
    if (isAnimating || isThinking || !isChatOpen) return;
    isChatOpen = false;
    isMinimized = true;
    if (!minimizedCustomPos) {
      minimizedCornerSide = currentDockSide;
    }

    try {
      window.getSelection().removeAllRanges();
    } catch (_) {}
    currentHighlight = '';
    lastPdfSelectedText = '';

    runMinimizeOrRestoreAnimation('minimize', () => {
      const targetPos = getActiveMinimizeTargetPos();
      resetBrainEyeAndBodyTracking();
      floatingIcon.classList.remove('ds-thinking', 'ds-sleeping', 'ds-notes-minimized');
      if (isNotesViewOpen) {
        floatingIcon.classList.add('ds-notes-minimized');
      } else {
        floatingIcon.classList.add('ds-sleeping');
      }
      floatingIcon.style.left = `${targetPos.x}px`;
      floatingIcon.style.top = `${targetPos.y}px`;
      brainCurrentPos = { x: targetPos.x, y: targetPos.y };
      floatingIcon.style.display = 'block';
      floatingIcon.title = "Chat minimized (Sleeping) — Click 3D brain to wake & reopen your session!";
      isAtRest = true;
    });
  }

  function triggerRestoreFromMinimizeTransition() {
    if (isAnimating || isThinking || isChatOpen || !isMinimized) return;
    isMinimized = false;
    if (floatingIcon) floatingIcon.classList.remove('ds-sleeping', 'ds-notes-minimized');

    // If the user moved the icon while minimized, open (and dock) on the side of the screen it was moved to!
    if (minimizedCustomPos) {
      const movedCenterX = minimizedCustomPos.x + ICON_RADIUS;
      const movedCenterY = minimizedCustomPos.y + ICON_RADIUS;
      currentDockSide = movedCenterX >= (window.innerWidth / 2) ? 'right' : 'left';
      minimizedCornerSide = currentDockSide;
      // Update iconOrigin to this moved location so if the user later clicks Exit (X), it closes right back to this moved spot and stays idle here!
      iconOrigin = {
        x: movedCenterX,
        y: movedCenterY,
        baselineY: Math.min(window.innerHeight - 20, movedCenterY + 32)
      };
    } else {
      currentDockSide = minimizedCornerSide;
    }

    runMinimizeOrRestoreAnimation('restore', () => {
      floatingIcon.style.display = 'none';
      chatSidebar.classList.add('ds-open');
      chatSidebar.style.pointerEvents = 'auto';
      floatingIcon.title = "Highlight text on the page, then click the 3D brain to explain!";
      isChatOpen = true;
    });
  }

  function triggerCloseTransition() {
    if (isAnimating || isThinking || !isChatOpen) return;
    isChatOpen = false;
    isMinimized = false;
    minimizedCustomPos = null;
    if (floatingIcon) floatingIcon.classList.remove('ds-sleeping', 'ds-notes-minimized');
    sessionHighlight = '';
    sessionMessages = [];

    try {
      window.getSelection().removeAllRanges();
    } catch (_) {}
    currentHighlight = '';
    lastPdfSelectedText = '';

    runExponentialCurveAnimation('reverse', () => {
      floatingIcon.classList.remove('ds-thinking', 'ds-sleeping', 'ds-notes-minimized');
      floatingIcon.style.left = `${iconOrigin.x - ICON_RADIUS}px`;
      floatingIcon.style.top = `${iconOrigin.y - ICON_RADIUS}px`;
      brainCurrentPos = { x: iconOrigin.x - ICON_RADIUS, y: iconOrigin.y - ICON_RADIUS };
      floatingIcon.style.display = 'block';

      const sel = window.getSelection();
      const stillHighlighted = sel && !sel.isCollapsed && sel.toString().trim().length > 1;
      if (!stillHighlighted) {
        const rest = getRestPosition();
        isAtRest = true;
        animateBrainSwoop(rest.x, rest.y, true);
      }
    });
  }

  function appendMessage(role, text) {
    const list = chatSidebar.querySelector('#ds-messages-list');
    const div = document.createElement('div');
    div.className = `ds-msg ${role === 'user' ? 'ds-msg-user' : 'ds-msg-assistant'}`;
    div.innerHTML = String(text || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/^###\s+(.*)$/gm, '<strong style="color:#5c4216;font-size:1.05em;display:block;margin-top:6px;">$1</strong>')
      .replace(/^##\s+(.*)$/gm, '<strong style="color:#5c4216;font-size:1.08em;display:block;margin-top:8px;">$1</strong>')
      .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer" style="color:#6b4c18;text-decoration:underline;font-weight:600;">$1</a>')
      .replace(/\*\*(.*?)\*\*/g, '<strong style="color:#4a3512;">$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      .replace(/\n/g, '<br/>');
    list.appendChild(div);
    list.scrollTop = list.scrollHeight;
    return div;
  }

  async function handleFollowUpQuestion(questionText) {
    appendMessage('user', questionText);
    sessionMessages.push({ role: 'user', content: questionText });

    const loadingDiv = appendMessage('assistant', "Thinking...");

    const result = await requestChatFromExtension(
      {
        type: 'DEEPSEEK_CHAT_REQUEST',
        messages: sessionMessages
      },
      false,
      questionText
    );

    loadingDiv.remove();
    sessionMessages.push({ role: 'assistant', content: result.reply });
    appendMessage('assistant', result.reply);
  }

  function returnBrainToRestCorner() {
    if (isChatOpen || isAnimating || isThinking) return;
    ensureElements();
    currentHighlight = '';
    floatingIcon.classList.remove('ds-thinking', 'ds-sleeping', 'ds-notes-minimized');
    const rest = getRestPosition();
    if (!isAtRest) {
      isAtRest = true;
      animateBrainSwoop(rest.x, rest.y, true);
    } else {
      brainCurrentPos = { x: rest.x, y: rest.y };
      floatingIcon.style.left = `${rest.x}px`;
      floatingIcon.style.top = `${rest.y}px`;
      floatingIcon.style.display = 'block';
    }
  }

  // Helper to read selection from standard HTML DOM or same-origin document iframes (e.g. Google Docs)
  function getActiveDomSelection() {
    const sel = window.getSelection();
    const text = sel && !sel.isCollapsed ? sel.toString().trim() : '';
    if (text.length > 1) {
      try {
        const range = sel.getRangeAt(0);
        const rect = range.getBoundingClientRect();
        if (rect.width > 0 || rect.height > 0) {
          return { text, rect };
        }
      } catch (_) {}
    }

    // Check Google Docs / embedded same-origin editor iframes
    try {
      const docIframes = document.querySelectorAll('iframe.docs-texteventtarget-iframe, iframe');
      for (const ifr of docIframes) {
        try {
          const ifrDoc = ifr.contentDocument || ifr.contentWindow?.document;
          if (!ifrDoc) continue;
          const ifrSel = ifrDoc.getSelection();
          const ifrText = ifrSel && !ifrSel.isCollapsed ? ifrSel.toString().trim() : '';
          if (ifrText.length > 1) {
            const ifrRect = ifr.getBoundingClientRect();
            return {
              text: ifrText,
              rect: {
                left: ifrRect.left + ifrRect.width * 0.4,
                right: ifrRect.left + ifrRect.width * 0.6,
                top: Math.max(80, lastKnownMousePos.y - 12),
                bottom: Math.max(100, lastKnownMousePos.y + 12),
                width: 120,
                height: 24
              }
            };
          }
        } catch (_) {}
      }
    } catch (_) {}

    return null;
  }

  let lastKnownMousePos = { x: window.innerWidth * 0.55, y: window.innerHeight * 0.32 };
  let lastPdfSelectedText = '';
  let pdfCursorSensor = null;

  function ensurePdfCursorSensor() {
    if (!pdfCursorSensor) {
      pdfCursorSensor = document.createElement('div');
      pdfCursorSensor.id = 'ds-pdf-cursor-sensor';
      pdfCursorSensor.style.cssText = 'position:fixed !important;inset:0 !important;width:100vw !important;height:100vh !important;z-index:2147483644 !important;background:transparent !important;pointer-events:none !important;';
      const rootTarget = document.body || document.documentElement;
      if (rootTarget) rootTarget.appendChild(pdfCursorSensor);
    }
    return pdfCursorSensor;
  }

  /**
   * Captures the exact cursor coordinates over a Chrome PDF <embed> plugin in 1 frame
   * without blocking any clicks or scrolling in the PDF, then swoops the 3D brain to that spot!
   */
  function capturePdfHighlightPositionAndSwoop(highlightedPdfText) {
    ensureElements();
    const sensor = ensurePdfCursorSensor();
    let captured = false;

    function finishSwoop(clientX, clientY) {
      if (captured) return;
      captured = true;
      sensor.style.pointerEvents = 'none';
      sensor.removeEventListener('mousemove', onSensorMove);

      currentHighlight = highlightedPdfText;
      const iconX = Math.min(window.innerWidth - (ICON_SIZE + 16), Math.max(16, clientX + 14));
      const iconY = Math.max(16, clientY - (ICON_SIZE - 4));

      iconOrigin = {
        x: iconX + ICON_RADIUS,
        y: iconY + ICON_RADIUS,
        baselineY: Math.min(window.innerHeight - 20, Math.max(clientY + 18, iconY + 60))
      };

      floatingIcon.classList.remove('ds-thinking', 'ds-sleeping', 'ds-notes-minimized');
      isAtRest = false;
      animateBrainSwoop(iconX, iconY, false);
    }

    function onSensorMove(e) {
      lastKnownMousePos = { x: e.clientX, y: e.clientY };
      finishSwoop(e.clientX, e.clientY);
    }

    sensor.addEventListener('mousemove', onSensorMove, { once: true });
    sensor.style.pointerEvents = 'auto';

    // Fallback timeout (110ms) if the user holds their mouse completely still after highlighting in the PDF
    setTimeout(() => {
      if (!captured) {
        finishSwoop(lastKnownMousePos.x, lastKnownMousePos.y);
      }
    }, 110);
  }

  // Listen for Chrome's built-in PDF Viewer Scripting API replies ({ type: 'getSelectedTextReply', selectedText: '...' })
  window.addEventListener('message', (e) => {
    if (!e.data || typeof e.data !== 'object') return;
    if (e.data.type === 'getSelectedTextReply' && typeof e.data.selectedText === 'string') {
      if (isAnimating || isThinking || isChatOpen) return;
      const pdfText = e.data.selectedText.trim();

      if (pdfText.length > 1) {
        if (pdfText !== lastPdfSelectedText) {
          lastPdfSelectedText = pdfText;
          hideSendHomeButton();
          capturePdfHighlightPositionAndSwoop(pdfText);
        } else {
          currentHighlight = pdfText;
        }
      } else if (lastPdfSelectedText !== '') {
        // User deselected text inside the PDF -> swoop brain back to its resting spot!
        lastPdfSelectedText = '';
        returnBrainToRestCorner();
      }
    }
  });

  // Also listen for right-click context menu selection triggers from background.js
  chrome.runtime.onMessage.addListener((msg) => {
    if (msg && msg.type === 'DEEPSEEK_PDF_CONTEXT_SELECTION' && msg.selectionText) {
      lastPdfSelectedText = msg.selectionText;
      currentHighlight = msg.selectionText;
      capturePdfHighlightPositionAndSwoop(msg.selectionText);
      setTimeout(() => {
        triggerThinkingThenTransition();
      }, 460);
    }
  });

  // Poll Chrome's built-in PDF Viewer (both OOPIF closed ShadowRoot iframe and <embed> postMessage) every 180ms
  setInterval(() => {
    if (isAnimating || isThinking || isChatOpen) return;
    const pdfEmbed = document.querySelector('embed[type="application/pdf"], embed[type="application/x-google-chrome-pdf"]');
    if (!pdfEmbed) return;

    // 1. Try Chrome 124+ OOPIF PDF Viewer internal iframe inside closed ShadowRoot
    try {
      const shadow = (typeof chrome !== 'undefined' && chrome.dom && typeof chrome.dom.openOrClosedShadowRoot === 'function')
        ? chrome.dom.openOrClosedShadowRoot(pdfEmbed)
        : pdfEmbed.shadowRoot;
      if (shadow) {
        const innerIframe = shadow.querySelector('iframe');
        if (innerIframe && innerIframe.contentWindow) {
          innerIframe.contentWindow.postMessage({ type: 'getSelectedText' }, '*');
        }
      }
    } catch (_) {}

    // 2. Try direct embed.postMessage if exposed in this world
    if (typeof pdfEmbed.postMessage === 'function') {
      try {
        pdfEmbed.postMessage({ type: 'getSelectedText' });
      } catch (_) {
        try {
          pdfEmbed.postMessage({ type: 'getSelectedText' }, '*');
        } catch (__) {}
      }
    }
  }, 180);

  function updateIconFromSelection() {
    if (isAnimating || isThinking || isChatOpen) return;
    const domSel = getActiveDomSelection();
    if (domSel && domSel.text.length > 1) {
      const text = domSel.text;
      const rect = domSel.rect;



      ensureElements();
      currentHighlight = text;

      const iconX = Math.min(window.innerWidth - (ICON_SIZE + 12), Math.max(12, rect.right + 4));
      const iconY = Math.max(12, rect.top - (ICON_SIZE - 4));

      iconOrigin = {
        x: iconX + ICON_RADIUS,
        y: iconY + ICON_RADIUS,
        baselineY: Math.min(window.innerHeight - 20, Math.max(rect.bottom + 10, iconY + 60))
      };

      floatingIcon.classList.remove('ds-thinking', 'ds-sleeping', 'ds-notes-minimized');
      isAtRest = false;
      animateBrainSwoop(iconX, iconY, false);
    } else if (!lastPdfSelectedText) {
      returnBrainToRestCorner();
    }
  }

  function findFrameElementForWindow(sourceWin) {
    const frames = document.querySelectorAll('iframe, frame, object, embed');
    for (const fr of frames) {
      try {
        if (fr.contentWindow === sourceWin) return fr;
      } catch (_) {}
    }
    return null;
  }

  /**
   * Hop-by-hop iframe relay for Canvas LMS PDF Previews (CanvaDocs, Files Preview Modal, Box Preview, etc.):
   * Child iframes relay selection rects, double-clicks, and mousemove coordinates up to window.top,
   * adding each iframe's bounding client rect offset along the way so the single 3D brain in window.top
   * swoops right to the highlighted text inside the Canvas preview!
   */
  window.addEventListener('message', (e) => {
    const d = e.data;
    if (!d || typeof d !== 'object' || d.type !== 'DS_FRAME_RELAY') return;

    const frameEl = findFrameElementForWindow(e.source);
    const offsetLeft = frameEl ? frameEl.getBoundingClientRect().left : 0;
    const offsetTop = frameEl ? frameEl.getBoundingClientRect().top : 0;

    const translated = {
      ...d,
      x: (d.x || 0) + offsetLeft,
      y: (d.y || 0) + offsetTop,
      rect: d.rect
        ? {
            left: d.rect.left + offsetLeft,
            right: d.rect.right + offsetLeft,
            top: d.rect.top + offsetTop,
            bottom: d.rect.bottom + offsetTop,
            width: d.rect.width,
            height: d.rect.height
          }
        : null
    };

    if (!IS_TOP_FRAME) {
      window.parent.postMessage(translated, '*');
      return;
    }

    if (isAnimating || isThinking || isChatOpen) return;

    if (translated.action === 'mousemove') {
      lastKnownMousePos = { x: translated.x, y: translated.y };
      if (!floatingIcon) return;
      const rotatorEl = floatingIcon.querySelector('.ds-brain-rotator');
      if (!rotatorEl) return;
      const cx = (brainCurrentPos.x || getRestPosition().x) + ICON_RADIUS;
      const cy = (brainCurrentPos.y || getRestPosition().y) + ICON_RADIUS;
      const dx = translated.x - cx;
      const dy = translated.y - cy;
      const flipX = dx > 0 ? -1 : 1;
      const pitchDeg = Math.max(-25, Math.min(25, -dy * 0.085));
      rotatorEl.style.transform = `scaleX(${flipX}) rotate(${pitchDeg.toFixed(1)}deg)`;
    } else if (translated.action === 'tripleclick' || translated.action === 'dblclick') {
      dblClickCooldownUntil = performance.now() + 420;
      hideSendHomeButton();
      currentHighlight = '';
      const targetX = Math.min(window.innerWidth - ICON_SIZE - 12, Math.max(12, translated.x - ICON_RADIUS));
      const targetY = Math.min(window.innerHeight - ICON_SIZE - 12, Math.max(38, translated.y - ICON_RADIUS));
      customIdlePos = { x: targetX, y: targetY };
      if (isMinimized) {
        minimizedCustomPos = { x: targetX, y: targetY };
        minimizedCornerSide = (targetX + ICON_RADIUS) >= (window.innerWidth / 2) ? 'right' : 'left';
        currentDockSide = minimizedCornerSide;
      }
      isAtRest = true;
      animateBrainSwoop(targetX, targetY, false);
    } else if (translated.action === 'selection' && translated.text && translated.rect) {
      ensureElements();
      hideSendHomeButton();
      currentHighlight = translated.text;
      lastPdfSelectedText = translated.text;
      const r = translated.rect;
      const iconX = Math.min(window.innerWidth - (ICON_SIZE + 12), Math.max(12, r.right + 4));
      const iconY = Math.max(12, r.top - (ICON_SIZE - 4));
      iconOrigin = {
        x: iconX + ICON_RADIUS,
        y: iconY + ICON_RADIUS,
        baselineY: Math.min(window.innerHeight - 20, Math.max(r.bottom + 10, iconY + 60))
      };
      floatingIcon.classList.remove('ds-thinking', 'ds-sleeping', 'ds-notes-minimized');
      isAtRest = false;
      animateBrainSwoop(iconX, iconY, false);
    } else if (translated.action === 'clear_selection') {
      lastPdfSelectedText = '';
      if (!isAtRest) {
        returnBrainToRestCorner();
      }
    }
  });

  function setupChildFrameRelay() {
    if (IS_TOP_FRAME) return;
    let childDblClickCooldown = 0;

    document.addEventListener('mousemove', (e) => {
      window.parent.postMessage({
        type: 'DS_FRAME_RELAY',
        action: 'mousemove',
        x: e.clientX,
        y: e.clientY
      }, '*');
    }, { passive: true });

    document.addEventListener('click', (e) => {
      if (e.detail === 3) {
        childDblClickCooldown = performance.now() + 420;
        try {
          window.getSelection().removeAllRanges();
        } catch (_) {}
        window.parent.postMessage({
          type: 'DS_FRAME_RELAY',
          action: 'tripleclick',
          x: e.clientX,
          y: e.clientY
        }, '*');
      }
    });

    function checkChildSelection() {
      if (performance.now() < childDblClickCooldown) return;
      const domSel = getActiveDomSelection();
      if (domSel && domSel.text.length > 1) {
        window.parent.postMessage({
          type: 'DS_FRAME_RELAY',
          action: 'selection',
          text: domSel.text,
          rect: {
            left: domSel.rect.left,
            right: domSel.rect.right,
            top: domSel.rect.top,
            bottom: domSel.rect.bottom,
            width: domSel.rect.width,
            height: domSel.rect.height
          }
        }, '*');
      } else {
        window.parent.postMessage({
          type: 'DS_FRAME_RELAY',
          action: 'clear_selection'
        }, '*');
      }
    }

    document.addEventListener('mouseup', (e) => {
      if (e.detail >= 3) return;
      const delay = e.detail === 2 ? 280 : 35;
      setTimeout(checkChildSelection, delay);
    });
    document.addEventListener('keyup', () => setTimeout(checkChildSelection, 50));
  }

  function resetBrainEyeAndBodyTracking() {
    if (!floatingIcon) return;
    const rotatorEl = floatingIcon.querySelector('.ds-brain-rotator');
    if (rotatorEl) rotatorEl.style.transform = 'none';
  }

  function updateBrainRotationForCursor(clientX, clientY) {
    lastKnownMousePos = { x: clientX, y: clientY };
    if (!floatingIcon || isThinking || isAnimating || isChatOpen || isMinimized) return;
    const rotatorEl = floatingIcon.querySelector('.ds-brain-rotator');
    if (!rotatorEl) return;

    const cx = (brainCurrentPos.x || getRestPosition().x) + ICON_RADIUS;
    const cy = (brainCurrentPos.y || getRestPosition().y) + ICON_RADIUS;
    const dx = clientX - cx;
    const dy = clientY - cy;

    // Flip horizontally if cursor crosses past the horizontal halfway point (cx) of the icon
    const flipX = dx > 0 ? -1 : 1;

    // Vertical angular increase when cursor is higher (dy < 0) and decrease when cursor is lower (dy > 0)
    const pitchDeg = Math.max(-25, Math.min(25, -dy * 0.085));
    rotatorEl.style.transform = `scaleX(${flipX}) rotate(${pitchDeg.toFixed(1)}deg)`;
  }

  // Top-level mousemove listener for HTML pages & PDF margin zones
  document.addEventListener('mousemove', (e) => {
    if (!IS_TOP_FRAME) return;
    updateBrainRotationForCursor(e.clientX, e.clientY);
  }, { passive: true });

  /**
   * Seamless Standalone PDF Engine (ONLY for full-window downloaded file:/// PDFs & direct PDF tabs):
   * - Never runs on HTML pages or Canvas LMS previews (those use normal DOM & child-frame relay).
   * - Never shows a loading screen: keeps Chrome's native PDF view visible until Page 1 is 100%
   *   rendered in the background, then seamlessly mounts the selectable PDF text layer styled
   *   identically to Chrome's native PDF viewer (#323639 top bar + #525659 backdrop) so highlighting
   *   text, cursor tracking, and double-click relocation work natively on downloaded PDFs!
   */
  let standalonePdfMounted = false;
  let pdfScale = 1.45;
  let cachedPdfBase64 = null;
  let totalPdfPages = 0;
  let renderedPagesCount = 0;

  function isStandalonePdfTab() {
    if (!IS_TOP_FRAME) return false;
    if (document.contentType === 'application/pdf') return true;
    const directEmbed = document.querySelector('body > embed[type="application/pdf"], body > embed[type="application/x-google-chrome-pdf"], body > iframe[src*="efaidnbmnnnibpcajpcglclefindmkaj"]');
    if (directEmbed) return true;
    if (/^file:\/\/.*\.pdf($|\?|#)/i.test(window.location.href)) return true;
    return false;
  }

  function arrayBufferToBase64(buf) {
    const bytes = new Uint8Array(buf);
    let binary = '';
    const chunkSize = 0x8000;
    for (let i = 0; i < bytes.length; i += chunkSize) {
      binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize));
    }
    return btoa(binary);
  }

  function readPdfViaXhr(url) {
    return new Promise((resolve) => {
      try {
        const xhr = new XMLHttpRequest();
        xhr.open('GET', url, true);
        xhr.responseType = 'arraybuffer';
        xhr.onload = () => {
          if ((xhr.status === 200 || xhr.status === 0) && xhr.response && xhr.response.byteLength > 0) {
            resolve(arrayBufferToBase64(xhr.response));
          } else {
            resolve(null);
          }
        };
        xhr.onerror = () => resolve(null);
        xhr.send();
      } catch (_) {
        resolve(null);
      }
    });
  }

  async function fetchStandalonePdfBase64() {
    if (cachedPdfBase64) return cachedPdfBase64;

    // 1. Ask background service worker first (has "<all_urls>" and "file:///*" host_permissions, bypassing file:// origin 'null' restrictions!)
    const bgB64 = await new Promise((resolve) => {
      try {
        chrome.runtime.sendMessage({ type: 'DEEPSEEK_FETCH_PDF_BASE64', url: window.location.href }, (resp) => {
          if (!chrome.runtime.lastError && resp && resp.ok && resp.base64) {
            resolve(resp.base64);
          } else {
            resolve(null);
          }
        });
      } catch (_) {
        resolve(null);
      }
    });
    if (bgB64) {
      cachedPdfBase64 = bgB64;
      return cachedPdfBase64;
    }

    // 2. Fallback to XMLHttpRequest
    const xhrB64 = await readPdfViaXhr(window.location.href);
    if (xhrB64) {
      cachedPdfBase64 = xhrB64;
      return cachedPdfBase64;
    }

    // 2. Try standard fetch (for https:// PDFs)
    try {
      const res = await fetch(window.location.href, { credentials: 'include' });
      if (res.ok) {
        const buf = await res.arrayBuffer();
        if (buf.byteLength > 0) {
          cachedPdfBase64 = arrayBufferToBase64(buf);
          return cachedPdfBase64;
        }
      }
    } catch (_) {}

    // 3. Fallback to background service worker fetch
    return new Promise((resolve) => {
      try {
        chrome.runtime.sendMessage({ type: 'DEEPSEEK_FETCH_PDF_BASE64', url: window.location.href }, (resp) => {
          if (resp && resp.ok && resp.base64) {
            cachedPdfBase64 = resp.base64;
            resolve(cachedPdfBase64);
          } else {
            resolve(null);
          }
        });
      } catch (_) {
        resolve(null);
      }
    });
  }

  async function decompressFlateChunk(uint8Slice) {
    for (const fmt of ['deflate', 'deflate-raw']) {
      try {
        const ds = new DecompressionStream(fmt);
        const writer = ds.writable.getWriter();
        writer.write(uint8Slice);
        writer.close();
        const outBuf = await new Response(ds.readable).arrayBuffer();
        return new TextDecoder('latin1').decode(outBuf);
      } catch (_) {}
    }
    return '';
  }

  async function renderBuiltInSelectablePdfPages(base64, pagesViewport, viewerRoot, pageCountLabel) {
    if (!base64 || renderedPagesCount > 0) return;
    try {
      const raw = atob(base64);
      const bytes = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);

      const extractedLines = [];
      let searchPos = 0;
      let streamCount = 0;

      while (searchPos < raw.length && streamCount < 90) {
        const sIdx = raw.indexOf('stream', searchPos);
        if (sIdx === -1) break;
        let dataStart = sIdx + 6;
        if (raw[dataStart] === '\r' && raw[dataStart + 1] === '\n') dataStart += 2;
        else if (raw[dataStart] === '\n' || raw[dataStart] === '\r') dataStart += 1;
        else {
          searchPos = sIdx + 6;
          continue;
        }
        const eIdx = raw.indexOf('endstream', dataStart);
        if (eIdx === -1) break;
        searchPos = eIdx + 9;

        const sliceLen = eIdx - dataStart;
        if (sliceLen > 10 && sliceLen < 450000) {
          streamCount++;
          const decompressed = await decompressFlateChunk(bytes.subarray(dataStart, eIdx));
          if (decompressed && decompressed.includes('BT')) {
            const btBlocks = decompressed.match(/BT[\s\S]*?ET/g) || [];
            for (const blk of btBlocks) {
              const strMatches = blk.match(/\((?:\\.|[^\\()])*\)/g) || [];
              if (strMatches.length > 0) {
                const line = strMatches
                  .map((tok) =>
                    tok
                      .slice(1, -1)
                      .replace(/\\n/g, ' ')
                      .replace(/\\r/g, ' ')
                      .replace(/\\\(/g, '(')
                      .replace(/\\\)/g, ')')
                      .replace(/\\\\/g, '\\')
                  )
                  .join('')
                  .replace(/[^\x20-\x7E\u00A0-\u00FF]/g, ' ')
                  .replace(/\s+/g, ' ')
                  .trim();
                if (line.length > 1) extractedLines.push(line);
              }
            }
          }
        }
      }

      if (extractedLines.length === 0) return;
      pagesViewport.innerHTML = '';
      const linesPerPage = 38;
      const numPages = Math.max(1, Math.ceil(extractedLines.length / linesPerPage));
      if (pageCountLabel) pageCountLabel.textContent = `1 / ${numPages}`;

      for (let p = 0; p < numPages; p++) {
        const pageLines = extractedLines.slice(p * linesPerPage, (p + 1) * linesPerPage);
        const card = document.createElement('div');
        card.className = 'ds-pdf-page-card';
        card.style.cssText = `width:${Math.round(680 * pdfScale)}px !important;min-height:${Math.round(860 * pdfScale)}px !important;padding:48px 56px !important;background:#ffffff !important;color:#0f172a !important;box-sizing:border-box !important;font-family:Georgia,serif !important;line-height:1.65 !important;font-size:${Math.round(11.5 * pdfScale)}px !important;user-select:text !important;`;
        card.innerHTML = pageLines.map((ln) => `<p style="margin:0 0 8px 0;user-select:text !important;cursor:text !important;">${ln.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</p>`).join('');
        pagesViewport.appendChild(card);
      }
      renderedPagesCount = numPages;
      revealStandalonePdfViewer(viewerRoot);
    } catch (_) {}
  }

  function revealStandalonePdfViewer(viewerRoot) {
    if (!viewerRoot) return;
    viewerRoot.style.setProperty('display', 'flex', 'important');
    const plugins = document.querySelectorAll('body > embed[type="application/pdf"], body > embed[type="application/x-google-chrome-pdf"], body > iframe[src*="efaidnbmnnnibpcajpcglclefindmkaj"]');
    plugins.forEach((el) => {
      if (el.id === 'ds-pdf-sandbox-iframe') return;
      el.style.setProperty('display', 'none', 'important');
      el.style.setProperty('pointer-events', 'none', 'important');
    });
  }

  async function mountSeamlessStandalonePdfBridge() {
    if (standalonePdfMounted || !isStandalonePdfTab()) return;
    standalonePdfMounted = true;

    const b64 = await fetchStandalonePdfBase64();
    if (!b64) return;

    // Create the viewer container HIDDEN (display: none) so the user NEVER sees a loading screen!
    // It only becomes visible at the exact millisecond Page 1 finishes rendering, styled identically to Chrome's native PDF viewer!
    const viewerRoot = document.createElement('div');
    viewerRoot.id = 'ds-pdf-viewer-root';
    viewerRoot.style.setProperty('display', 'none', 'important');
    viewerRoot.style.setProperty('background', '#525659', 'important');

    const rawFileName = decodeURIComponent(window.location.pathname.split('/').filter(Boolean).pop() || 'document.pdf');

    viewerRoot.innerHTML = `
      <div id="ds-pdf-toolbar" style="height:56px !important;background:#323639 !important;border-bottom:1px solid #202124 !important;display:flex !important;align-items:center !important;justify-content:space-between !important;padding:0 24px !important;color:#f1f3f4 !important;font-size:13px !important;">
        <div style="display:flex;align-items:center;gap:14px;min-width:0;max-width:38vw;">
          <span style="font-weight:500;color:#f1f3f4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${rawFileName}</span>
        </div>
        <div style="display:flex;align-items:center;gap:8px;">
          <span id="ds-pdf-page-count" style="background:#202124;padding:3px 10px;border-radius:4px;font-size:12px;color:#e8eaed;">1 / 1</span>
          <span style="color:#5f6368;margin:0 4px;">|</span>
          <button type="button" id="ds-pdf-zoom-out" style="background:transparent;border:none;color:#e8eaed;font-size:16px;padding:2px 8px;cursor:pointer;">−</button>
          <span id="ds-pdf-zoom-label" style="background:#202124;padding:3px 10px;border-radius:4px;min-width:48px;text-align:center;font-size:12px;color:#e8eaed;">100%</span>
          <button type="button" id="ds-pdf-zoom-in" style="background:transparent;border:none;color:#e8eaed;font-size:16px;padding:2px 8px;cursor:pointer;">+</button>
        </div>
        <div style="width:90px;"></div>
      </div>
      <div id="ds-pdf-pages-viewport" style="background:#525659 !important;"></div>
    `;

    (document.body || document.documentElement).appendChild(viewerRoot);

    const sandboxIframe = document.createElement('iframe');
    sandboxIframe.id = 'ds-pdf-sandbox-iframe';
    sandboxIframe.src = chrome.runtime.getURL('pdf_sandbox.html');
    sandboxIframe.style.cssText = 'position:fixed !important;width:0 !important;height:0 !important;border:none !important;opacity:0 !important;pointer-events:none !important;';
    (document.body || document.documentElement).appendChild(sandboxIframe);

    const pagesViewport = viewerRoot.querySelector('#ds-pdf-pages-viewport');
    const pageCountLabel = viewerRoot.querySelector('#ds-pdf-page-count');
    const zoomLabel = viewerRoot.querySelector('#ds-pdf-zoom-label');

    function triggerSandboxRender() {
      pagesViewport.innerHTML = '';
      renderedPagesCount = 0;
      sandboxIframe.contentWindow.postMessage({
        type: 'DS_RENDER_PDF_BASE64',
        base64: b64,
        scale: pdfScale
      }, '*');
      setTimeout(() => {
        if (renderedPagesCount === 0) {
          renderBuiltInSelectablePdfPages(b64, pagesViewport, viewerRoot, pageCountLabel);
        }
      }, 3200);
    }

    sandboxIframe.addEventListener('load', () => {
      triggerSandboxRender();
    });

    window.addEventListener('message', (e) => {
      const d = e.data;
      if (!d || typeof d !== 'object') return;

      if (d.type === 'DS_PDF_META') {
        totalPdfPages = d.numPages || 1;
        pageCountLabel.textContent = `1 / ${totalPdfPages}`;
        for (let p = 1; p <= totalPdfPages; p++) {
          const placeholder = document.createElement('div');
          placeholder.className = 'ds-pdf-page-card';
          placeholder.id = `ds-pdf-page-${p}`;
          placeholder.style.width = `${Math.round(612 * pdfScale)}px`;
          placeholder.style.height = `${Math.round(792 * pdfScale)}px`;
          pagesViewport.appendChild(placeholder);
        }
      } else if (d.type === 'DS_PDF_PAGE') {
        const card = document.getElementById(`ds-pdf-page-${d.pageNum}`);
        if (!card) return;
        card.style.width = `${Math.round(d.width)}px`;
        card.style.height = `${Math.round(d.height)}px`;
        card.innerHTML = '';

        const img = document.createElement('img');
        img.className = 'ds-pdf-page-img';
        img.src = d.dataUrl;
        card.appendChild(img);

        const textLayer = document.createElement('div');
        textLayer.className = 'ds-pdf-text-layer';
        card.appendChild(textLayer);

        // Reveal the viewer right when Page 1 is ready so the user never sees a loading screen
        if (renderedPagesCount === 0) {
          revealStandalonePdfViewer(viewerRoot);
        }

        const items = d.items || [];
        items.forEach((it) => {
          if (!it.str || !it.str.trim()) return;
          const span = document.createElement('span');
          span.textContent = it.str;
          span.style.left = `${it.left.toFixed(1)}px`;
          span.style.top = `${it.top.toFixed(1)}px`;
          span.style.fontSize = `${Math.max(6, it.fontHeight).toFixed(1)}px`;
          span.style.fontFamily = 'sans-serif';
          textLayer.appendChild(span);

          const actualW = span.getBoundingClientRect().width;
          if (actualW > 0 && it.width > 0) {
            const scaleX = it.width / actualW;
            if (scaleX > 0.2 && scaleX < 4.0) {
              span.style.transform = `scaleX(${scaleX.toFixed(3)})`;
            }
          }
        });

        renderedPagesCount++;
      } else if (d.type === 'DS_PDF_ERROR') {
        renderBuiltInSelectablePdfPages(b64, pagesViewport, viewerRoot, pageCountLabel);
      }
    });

    viewerRoot.querySelector('#ds-pdf-zoom-in').addEventListener('click', () => {
      pdfScale = Math.min(2.4, pdfScale + 0.2);
      zoomLabel.textContent = `${Math.round((pdfScale / 1.45) * 100)}%`;
      triggerSandboxRender();
    });

    viewerRoot.querySelector('#ds-pdf-zoom-out').addEventListener('click', () => {
      pdfScale = Math.max(0.85, pdfScale - 0.2);
      zoomLabel.textContent = `${Math.round((pdfScale / 1.45) * 100)}%`;
      triggerSandboxRender();
    });
  }

  function initExtensionOnPage() {
    if (IS_TOP_FRAME) {
      ensureElements();
      if (isStandalonePdfTab()) {
        mountSeamlessStandalonePdfBridge();
      }
    } else {
      setupChildFrameRelay();
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initExtensionOnPage);
  } else {
    initExtensionOnPage();
  }

  window.addEventListener('resize', () => {
    if (isChatOpen && !isAnimating) {
      applyFluidDockedStyles(currentDockSide === 'right');
    } else if (isAtRest && floatingIcon && !isSwooping) {
      const rest = getRestPosition();
      brainCurrentPos = { x: rest.x, y: rest.y };
      floatingIcon.style.left = `${rest.x}px`;
      floatingIcon.style.top = `${rest.y}px`;
    }
  });

  let dblClickCooldownUntil = 0;

  // Triple-clicking (e.detail === 3) anywhere on the page swoops the 3D brain to that spot to remain idle there
  document.addEventListener('click', (e) => {
    if (!IS_TOP_FRAME) return;
    if (e.detail !== 3) return;
    if (isAnimating || isThinking || isChatOpen) return;
    if (chatSidebar && chatSidebar.contains(e.target)) return;
    if (floatingIcon && floatingIcon.contains(e.target)) return;

    dblClickCooldownUntil = performance.now() + 420;
    hideSendHomeButton();

    try {
      window.getSelection().removeAllRanges();
    } catch (_) {}
    currentHighlight = '';
    lastPdfSelectedText = '';

    const targetX = Math.min(window.innerWidth - ICON_SIZE - 12, Math.max(12, e.clientX - ICON_RADIUS));
    const targetY = Math.min(window.innerHeight - ICON_SIZE - 12, Math.max(38, e.clientY - ICON_RADIUS));
    customIdlePos = { x: targetX, y: targetY };
    if (isMinimized) {
      minimizedCustomPos = { x: targetX, y: targetY };
      minimizedCornerSide = (targetX + ICON_RADIUS) >= (window.innerWidth / 2) ? 'right' : 'left';
      currentDockSide = minimizedCornerSide;
    }
    isAtRest = true;
    animateBrainSwoop(targetX, targetY, false);
  });

  document.addEventListener('mousedown', (e) => {
    if (floatingIcon && !floatingIcon.contains(e.target)) {
      hideSendHomeButton();
    }
  });

  document.addEventListener('mouseup', (e) => {
    if (!IS_TOP_FRAME) return;
    if (chatSidebar && chatSidebar.contains(e.target)) return;
    if (floatingIcon && floatingIcon.contains(e.target)) return;
    if (e.detail >= 3) return;
    const waitMs = e.detail === 2 ? 280 : 35;
    setTimeout(() => {
      if (performance.now() < dblClickCooldownUntil) return;
      updateIconFromSelection();
    }, waitMs);
  });

  document.addEventListener('keyup', (e) => {
    if (chatSidebar && chatSidebar.contains(e.target)) return;
    setTimeout(updateIconFromSelection, 10);
  });

  document.addEventListener('selectionchange', () => {
    if (isAnimating || isThinking || isChatOpen) return;
    if (performance.now() < dblClickCooldownUntil) return;
    if (lastPdfSelectedText) return;
    const sel = window.getSelection();
    const text = sel && !sel.isCollapsed ? sel.toString().trim() : '';
    if (!text && floatingIcon && !isAtRest) {
      returnBrainToRestCorner();
    }
  });
})();
